/**
 * The build marker the drawer prints, so a reader can tell which JavaScript is really running.
 *
 * The values are generated by `scripts/stamp-build.mjs` (`npm run stamp`) from the repository itself: the
 * short commit the bundle was built from and the moment the stamp was taken. A `+` after the hash means the
 * working tree had uncommitted changes when the stamp was written — which is exactly the "is Metro serving
 * the latest code?" question this line exists to answer.
 *
 * Regenerate it before a phone session, not on every edit: `node scripts/stamp-build.mjs`.
 */
export const BUILD_COMMIT = '2a8161d+';
export const BUILD_TIME = '2026-10-17T21:14:57.439Z';

/** `2a8161d · 17 oct 2026, 21:04 UTC` — the one line the drawer, and Settings › Despre, print. */
export function buildLine(): string {
  const moment = new Date(BUILD_TIME);
  if (Number.isNaN(moment.getTime())) return BUILD_COMMIT;
  const day = moment.toLocaleDateString('ro-RO', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' });
  const clock = moment.toLocaleTimeString('ro-RO', { hour: '2-digit', minute: '2-digit', timeZone: 'UTC' });
  return `${BUILD_COMMIT} · ${day}, ${clock} UTC`;
}
